enum Prec { None, Assign, Sum, Product, Unary, Call }
readonly Dictionary<TokenKind, (Func<Parser, Expr>? Nud, Func<Parser, Expr, Expr>? Led, Prec Prec)> _rules = new() {
  [TokenKind.Minus]  = (p => Neg(p),   (p, l) => Binary(l, p), Prec.Sum),
  [TokenKind.LParen] = (p => Group(p), (p, l) => Call(l, p),   Prec.Call),
};
Expr ParseExpr(Prec min) {
  var rule  = _rules[Next().Kind];
  var left  = rule.Nud!(this);                        // null denotation
  while (min <= _rules[Peek().Kind].Prec)             // left denotation
    left = _rules[Next().Kind].Led!(this, left);
  return left;
}
